/* ══════════ 39-data.js ══════════ */
/* ============================================================
   PebbleX v0.1 — 39-data.js
   Data & reliability:
     · live "saved 2s ago" indicator in the topbar
     · per-collection storage breakdown
     · CSV export for every module
     · settings search
     · automatic daily snapshots with rollback
     · offline / connectivity indicator
   ============================================================ */
(function(NX){
'use strict';
const { h, q, qa, util:U, icon } = NX;

/* ============================================================
   1. LAST SAVED
   ============================================================ */
const Save = {
  at: 0, count: 0,
  start(){
    const store = NX.store;
    if(store.__saveHooked) return;
    store.__saveHooked = true;
    const orig = store.set.bind(store);
    store.set = function(key, val){
      const r = orig(key, val);
      Save.at = Date.now();
      Save.count++;
      NX.events.emit('store:saved', { key });
      return r;
    };
    /* count what already happened this session */
    Save.at = Date.now();
  },
  ago(){
    if(!Save.at) return 'not saved yet';
    const s = Math.floor((Date.now() - Save.at)/1000);
    if(s < 3) return 'saved just now';
    if(s < 60) return 'saved ' + s + 's ago';
    const m = Math.floor(s/60);
    if(m < 60) return 'saved ' + m + 'm ago';
    return 'saved ' + Math.floor(m/60) + 'h ago';
  }
};
NX.saveState = Save;
Save.start();

/* ============================================================
   6. OFFLINE INDICATOR
   ============================================================ */
const Net = {
  online: true,
  aiDown: false,
  init(){
    this.online = navigator.onLine !== false;
    window.addEventListener('online', ()=>{ this.online = true;  NX.events.emit('net:changed'); });
    window.addEventListener('offline', ()=>{ this.online = false; NX.events.emit('net:changed'); });
    NX.events.on('net:changed', ()=> NX.toastInfo(this.online ? 'Back online' : 'Offline',
      this.online ? 'Everything will sync again' : 'Pebble keeps working — nothing is lost'));
  }
};
NX.net = Net;
Net.init();

/* ============================================================
   TOPBAR CHIPS — saved + offline + storage
   ============================================================ */
const _renderShell = NX.renderShell;
NX.renderShell = function(routeName){
  const view = _renderShell.apply(NX, arguments);
  try{
    const top = view.closest('.main-col');
    const bar = top && top.querySelector('#shell-top .topbar');
    if(bar && !bar.querySelector('#nx-status')){
      const chip = h(`<div class="nx-status" id="nx-status">
        <button class="nx-status-btn" id="nx-saved" data-tip="Last workspace save">${icon('check')}<span id="nx-saved-t">saved</span></button>
        <button class="nx-status-btn" id="nx-net" data-tip="Connection status">${icon('globe')}<span id="nx-net-t">online</span></button>
        <button class="icon-btn" id="nx-storage" data-tip="Storage & backups">${icon('layers')}</button>
      </div>`);
      bar.insertBefore(chip, bar.querySelector('#tp-search'));
      q('#nx-storage', chip).onclick = ()=>NX.openStorage();
      q('#nx-saved', chip).onclick = ()=>NX.openSnapshots();
    }
  }catch(e){}
  syncStatus();
  return view;
};

function syncStatus(){
  const saved = q('#nx-saved-t');
  if(saved) saved.textContent = Save.ago();
  const netT = q('#nx-net-t');
  const netB = q('#nx-net');
  if(netT && netB){
    const off = !Net.online;
    netT.textContent = off ? 'offline' : (Net.aiDown ? 'ai down' : 'online');
    netB.classList.toggle('warn', off || Net.aiDown);
    netB.setAttribute('data-tip', off ? 'No internet — everything still works locally'
      : Net.aiDown ? 'Pel AI is unreachable; on-device answers still work' : 'Connected');
  }
  const sc = q('#nx-saved');
  if(sc){
    const s = Math.floor((Date.now() - Save.at)/1000);
    sc.classList.toggle('warn', Save.at > 0 && s > 300);
    sc.setAttribute('data-tip', 'Last workspace save · ' + Save.count + ' writes this session');
  }
}
setInterval(syncStatus, 4000);
NX.events.on('store:saved', syncStatus);
NX.events.on('net:changed', syncStatus);

/* ============================================================
   2. STORAGE BREAKDOWN
   ============================================================ */
const COLLECTIONS = [
  { k:'notes',      n:'Notes',      ic:'notes' },
  { k:'tasks',      n:'Tasks',      ic:'todo' },
  { k:'messages',   n:'Chat',       ic:'chat' },
  { k:'prompts',    n:'Prompts',    ic:'star' },
  { k:'reminders',  n:'Reminders',  ic:'bell' },
  { k:'timeless',   n:'Timeless',   ic:'clock' },
  { k:'servers',    n:'Servers',    ic:'globe' },
  { k:'noteHistory',n:'Note history',ic:'history' },
  { k:'focus',      n:'Focus log',  ic:'timer' },
  { k:'gamePlays',  n:'Game stats', ic:'game' },
  { k:'snapshots',  n:'Snapshots',  ic:'shield' }
];
function sizeOf(key){
  let raw;
  try{ raw = localStorage.getItem('pebble.' + key); }catch(e){ raw = null; }
  return raw ? raw.length * 2 : 0;
}
function breakdown(){
  const rows = COLLECTIONS.map(c => ({ ...c, bytes: sizeOf(c.k) }))
    .filter(r => r.bytes > 0)
    .sort((a,b) => b.bytes - a.bytes);
  const total = rows.reduce((a,r) => a + r.bytes, 0);
  return { rows, total };
}
NX.storageBreakdown = breakdown;

NX.openStorage = function(){
  const { rows, total } = breakdown();
  const peak = Math.max(1, ...rows.map(r => r.bytes));
  const counts = {
    notes:(NX.store.get('notes',[])||[]).length,
    tasks:(NX.store.get('tasks',[])||[]).length,
    prompts:(NX.store.get('prompts',[])||[]).length,
    reminders:(NX.store.get('reminders',[])||[]).length
  };
  NX.modal({
    title:'Storage & backups', icon:'layers', size:'m-lg',
    body:`<div class="store">
      <div class="store-total">
        <div><b>${(total/1024).toFixed(1)} KB</b><i>of local workspace data</i></div>
        <div style="flex:1"></div>
        <button class="btn btn-soft btn-sm" id="store-backup">${icon('download')} Export backup</button>
        <button class="btn btn-soft btn-sm" id="store-snap">${icon('shield')} Snapshots</button>
      </div>
      <div class="store-rows">
        ${rows.map(r=>`
          <div class="store-row">
            <span class="store-ic">${icon(r.ic)}</span>
            <span class="store-txt">
              <b>${U.esc(r.n)}</b>
              <i>${counts[r.k] != null ? counts[r.k] + ' item' + (counts[r.k]===1?'':'s') : (Array.isArray(NX.store.get(r.k)) ? NX.store.get(r.k).length + ' entries' : '')}</i>
              <span class="meter"><i style="width:${Math.round(r.bytes/peak*100)}%"></i></span>
            </span>
            <span class="store-bytes">${r.bytes < 1024 ? r.bytes + ' B' : (r.bytes/1024).toFixed(1) + ' KB'}</span>
            <button class="icon-btn sm" data-clear="${r.k}" data-tip="Clear ${U.esc(r.n.toLowerCase())}">${icon('trash')}</button>
          </div>`).join('') || '<div class="empty" style="padding:26px"><div class="e-sub">Nothing stored yet.</div></div>'}
      </div>
      <p class="tiny faint" style="margin:0">Clearing a collection is undoable for the rest of the session.</p>
    </div>`,
    footer:[{ label:'Close', cls:'btn-soft' }]
  });
  const back = q('.modal-backdrop');
  if(!back) return;
  q('#store-backup', back).onclick = ()=>NX.exportWorkspace();
  q('#store-snap', back).onclick = ()=>{ NX.closeAllModals(); NX.openSnapshots(); };
  qa('[data-clear]', back).forEach(b=>b.onclick = ()=>{
    const k = b.dataset.clear;
    const was = NX.store.get(k, null);
    NX.store.set(k, Array.isArray(was) ? [] : (typeof was === 'object' && was ? {} : 0));
    NX.toastInfo('Cleared ' + k, 'Undo restores it', { action:{ label:'Undo', onClick:()=>{
      NX.store.set(k, was);
      NX.toastOk('Restored ' + k);
      NX.openStorage();
    } } });
  });
};

/* ============================================================
   5. DAILY SNAPSHOTS
   ============================================================ */
const SNAP_MAX = 7;
function snaps(){ const s = NX.store.get('snapshots', {}); return s && typeof s === 'object' ? s : {}; }
function snapKey(){ return U.todayKey(); }
function takeSnapshot(label){
  try{
    const dump = NX.store.dump();
    delete dump.snapshots;
    const all = snaps();
    const s = Object.assign({}, all);
    s[snapKey()] = { at:Date.now(), label: label || 'Auto', keys:Object.keys(dump).length, dump };
    const keys = Object.keys(s).sort();
    while(keys.length > SNAP_MAX) delete s[keys.shift()];
    NX.store.set('snapshots', s);
    NX.events.emit('snap:changed');
    return true;
  }catch(e){ return false; }
}
NX.snapshots = {
  take: takeSnapshot,
  list(){ return Object.keys(snaps()).sort().reverse().map(k => Object.assign({ key:k }, snaps()[k])); },
  restore(key){
    const s = snaps()[key];
    if(!s || !s.dump) return false;
    const current = NX.store.dump();
    const keep = ['snapshots'];
    NX.store.restore(s.dump);
    keep.forEach(k => NX.store.set(k, current[k]));
    NX.events.emit('snap:changed');
    NX.toastOk('Workspace restored', 'Snapshot from ' + new Date(s.at).toLocaleString());
    NX.undoable('Rolled back to a snapshot', new Date(s.at).toLocaleString(), ()=>{
      NX.store.restore(current);
      NX.toastOk('Back to your current data');
    }, { life:8000 });
    return true;
  }
};

let lastSnapDay = null;
function autoSnapshot(){
  const k = snapKey();
  if(lastSnapDay === k) return;
  lastSnapDay = k;
  if(!snaps()[k]) takeSnapshot('Auto · start of day');
}
document.addEventListener('DOMContentLoaded', ()=> setTimeout(autoSnapshot, 1200));

/* a bulk import is the single most destructive thing a user can do —
   take a safety net first. (Patching NX.store.restore is not enough:
   importWorkspace closes over the internal Store object.) */
const _import = NX.importWorkspace;
NX.importWorkspace = function(){
  try{ takeSnapshot('Before import'); }catch(e){}
  return _import.apply(NX, arguments);
};

NX.openSnapshots = function(){
  const list = NX.snapshots.list();
  NX.modal({
    title:'Snapshots', icon:'shield', size:'m-lg',
    body: list.length
      ? `<div class="ag-list">${list.map(s=>`
          <div class="ag-row">
            <span class="ag-ic">${icon('shield')}</span>
            <span class="ag-txt">
              <b>${U.esc(s.label || 'Snapshot')}</b>
              <i>${U.esc(new Date(s.at).toLocaleString())} · ${s.keys || 0} collections</i>
            </span>
            <button class="btn btn-soft btn-sm" data-roll="${s.key}">Roll back</button>
          </div>`).join('')}</div>
         <p class="tiny faint" style="margin:14px 0 0">Pebble keeps ${SNAP_MAX} daily snapshots. Rolling back is itself undoable.</p>`
      : `<div class="empty" style="padding:34px"><div class="e-title">No snapshots yet</div>
         <div class="e-sub">One is taken automatically at the start of each day, and before any bulk restore.</div>
         <button class="btn btn-green" id="snap-take">${icon('plus')} Take one now</button></div>`,
    footer:[{ label:'Take a snapshot', cls:'btn-soft', onClick:()=>{ takeSnapshot('Manual'); NX.closeAllModals(); NX.openSnapshots(); } }]
  });
  const back = q('.modal-backdrop');
  if(!back) return;
  const take = q('#snap-take', back);
  if(take) take.onclick = ()=>{ takeSnapshot('Manual'); NX.closeAllModals(); NX.openSnapshots(); };
  qa('[data-roll]', back).forEach(b=>b.onclick = ()=>{
    const key = b.dataset.roll;
    NX.closeAllModals();
    NX.confirm('Roll back to this snapshot?',
      'Your current workspace is replaced by the copy from ' + new Date(snaps()[key].at).toLocaleString() + '. You can undo this afterwards.',
      ()=>{
        NX.snapshots.restore(key);
        setTimeout(()=>NX.router.go('dashboard'), 120);
      }, { icon:'history', yes:'Roll back', danger:false });
  });
};

/* ============================================================
   3. CSV EXPORT
   ============================================================ */
function csvCell(v){
  const s = String(v == null ? '' : v).replace(/\r?\n/g,' ');
  return /[",]/.test(s) ? '"' + s.replace(/"/g,'""') + '"' : s;
}
function csv(rows){
  return rows.map(r => r.map(csvCell).join(',')).join('\r\n');
}
const CSV = {
  notes(){
    const rows = [['id','title','folder','tags','updated','chars']];
    (NX.store.get('notes', []) || []).forEach(n => rows.push([
      n.id, n.title || 'Untitled', n.folder || '',
      Array.isArray(n.tags) ? n.tags.join(' ') : '',
      n.updated ? new Date(n.updated).toISOString() : '',
      String(n.body || '').length
    ]));
    return { name:'pebble-notes.csv', body:csv(rows) };
  },
  tasks(){
    const rows = [['id','name','done','important','myDay','due','list','repeat','estimateMin','actualMin','created']];
    (NX.store.get('tasks', []) || []).forEach(t => rows.push([
      t.id, t.name || '', t.done?'yes':'no', t.important?'yes':'no', t.myDay?'yes':'no',
      t.due || '', t.listId || t.cat || '', t.repeat || 'none', t.estimateMin || 0,
      Math.round((t.timeLinked || 0)/60), t.created ? new Date(t.created).toISOString() : ''
    ]));
    return { name:'pebble-tasks.csv', body:csv(rows) };
  },
  prompts(){
    const rows = [['id','title','tags','favorite','created']];
    (NX.store.get('prompts', []) || []).forEach(p => rows.push([
      p.id, p.title || '', Array.isArray(p.tags) ? p.tags.join(' ') : '',
      p.favorite?'yes':'no', p.created ? new Date(p.created).toISOString() : ''
    ]));
    return { name:'pebble-prompts.csv', body:csv(rows) };
  },
  reminders(){
    const rows = [['id','name','when','repeat','category','fired']];
    (NX.store.get('reminders', []) || []).forEach(r => rows.push([
      r.id, r.name || '', r.when ? new Date(r.when).toISOString() : '',
      r.repeat || 'none', r.cat || '', r.fired?'yes':'no'
    ]));
    return { name:'pebble-reminders.csv', body:csv(rows) };
  },
  timeline(){
    const rows = [['day','app','category','seconds']];
    const tl = NX.store.get('timeless', {}) || {};
    Object.entries(tl).forEach(([day, d])=>{
      if(!d || typeof d !== 'object') return;
      Object.entries(d).forEach(([k, a])=>{
        if(k === '__hours' || !a || !a.sec) return;
        rows.push([day, k, a.cat || '', Math.round(a.sec)]);
      });
    });
    return { name:'pebble-timeline.csv', body:csv(rows) };
  },
  focus(){
    const rows = [['when','seconds','task','note']];
    const log = NX.focusLog ? NX.focusLog.rounds() : [];
    log.forEach(r => rows.push([
      r.at ? new Date(r.at).toISOString() : '', Math.round(r.sec || 0),
      r.task || '', r.note || ''
    ]));
    return { name:'pebble-focus-rounds.csv', body:csv(rows) };
  },
  chat(){
    const rows = [['channel','who','when','text']];
    const msgs = NX.store.get('messages', {}) || {};
    Object.entries(msgs).forEach(([ch, arr])=>{
      (arr || []).forEach(m => rows.push([ch, m.who || '', m.ts ? new Date(m.ts).toISOString() : '', m.text || '']));
    });
    return { name:'pebble-chat.csv', body:csv(rows) };
  }
};
NX.csvExport = CSV;
NX.exportCSV = function(kind){
  const fn = CSV[kind];
  if(!fn){ NX.toastErr('Unknown export', String(kind)); return false; }
  const out = fn();
  const lines = out.body.split('\r\n').length - 1;
  U.download(out.name, out.body);
  NX.toastOk('Exported ' + out.name, lines + (lines === 1 ? ' row' : ' rows'));
  return true;
};

NX.openExport = function(){
  const kinds = [
    ['notes','Notes', (NX.store.get('notes',[])||[]).length],
    ['tasks','Tasks', (NX.store.get('tasks',[])||[]).length],
    ['prompts','Prompts', (NX.store.get('prompts',[])||[]).length],
    ['reminders','Reminders', (NX.store.get('reminders',[])||[]).length],
    ['timeline','Timeless time log', Object.keys(NX.store.get('timeless',{})||{}).length],
    ['focus','Focus rounds', NX.focusLog ? NX.focusLog.rounds().length : 0],
    ['chat','Chat messages', Object.values(NX.store.get('messages',{})||{}).reduce((a,b)=>a+(b||[]).length,0)]
  ];
  NX.modal({
    title:'Export as CSV', icon:'download',
    body:`<div class="ag-list">
      ${kinds.map(([k,n,c])=>`<div class="ag-row">
        <span class="ag-ic">${icon('download')}</span>
        <span class="ag-txt"><b>${n}</b><i>${c} row${c===1?'':'s'}</i></span>
        <button class="btn btn-soft btn-sm" data-csv="${k}">Export</button>
      </div>`).join('')}
    </div>
    <p class="tiny faint" style="margin:14px 0 0">Opens in Excel, Numbers or Google Sheets.</p>`
  });
  const back = q('.modal-backdrop');
  if(back) qa('[data-csv]', back).forEach(b=>b.onclick = ()=>NX.exportCSV(b.dataset.csv));
};

/* ============================================================
   4. SETTINGS SEARCH
   ============================================================ */
NX.openSettingsSearch = function(){
  const sections = [...document.querySelectorAll('.set-nav [data-s]')].map(b => ({
    id:b.dataset.s, label:b.textContent.trim()
  }));
  const back = h(`<div class="qs-backdrop"><div class="gs-panel" role="dialog" aria-label="Search settings">
    <div class="gs-input-row">${icon('sliders')}<input placeholder="Search settings and options…" aria-label="Search settings"></div>
    <div class="gs-results" id="set-results"></div>
    <div class="gs-foot"><span class="tiny faint">↵ jump to section</span><span class="tiny faint">esc close</span></div>
  </div></div>`);
  const input = back.querySelector('input');
  const results = back.querySelector('#set-results');
  let rows = [];
  const ALIASES = {
    themes:['colour','color','dark','light','theme','accent'],
    profile:['name','avatar','picture','photo','plan'],
    customize:['motion','animation','compact','density','goal','widget','ambient','breath','eye','shortcut'],
    sound:['sfx','volume','mute','audio','noise'],
    hotkeys:['keyboard','shortcut','key','ctrl','binding','pin','recent','undo'],
    reliability:['crash','error','bug','diagnostic','repair','health'],
    storage:['size','disk','space','backup','snapshot','clear','reset'],
    about:['version','license','credit','update']
  };
  function run(){
    const qy = input.value.trim().toLowerCase();
    if(!qy){
      rows = sections;
      results.innerHTML = `<div class="ag-list">${rows.map((s,i)=>`
        <div class="ag-row" data-s="${s.id}">
          <span class="ag-ic">${icon('sliders')}</span>
          <span class="ag-txt"><b>${U.esc(s.label)}</b></span>
        </div>`).join('')}</div>`;
    } else {
      rows = sections.filter(s => {
        const hay = (s.label + ' ' + (ALIASES[s.id] || []).join(' ')).toLowerCase();
        return hay.indexOf(qy) > -1;
      });
      results.innerHTML = rows.length ? `<div class="ag-list">${rows.map(s=>`
        <div class="ag-row" data-s="${s.id}">
          <span class="ag-ic">${icon('sliders')}</span>
          <span class="ag-txt"><b>${U.esc(s.label)}</b>
            <i>${U.esc(((ALIASES[s.id]||[]).slice(0,5)).join(' · '))}</i></span>
        </div>`).join('')}</div>`
        : `<div class="gs-empty">Nothing matches “${U.esc(input.value)}”.</div>`;
    }
    qa('[data-s]', results).forEach(r=>r.onclick = ()=>{
      close();
      NX.router.go('settings');
      setTimeout(()=>{
        const btn = document.querySelector('.set-nav [data-s="' + r.dataset.s + '"]');
        if(btn) btn.click();
      }, 160);
    });
  }
  function close(){ back.remove(); document.removeEventListener('keydown', keyH); }
  function keyH(e){
    if(e.key === 'Escape'){ close(); }
    else if(e.key === 'Enter' && rows.length){
      const first = results.querySelector('[data-s]');
      if(first) first.click();
    }
  }
  back.addEventListener('pointerdown', e=>{ if(e.target === back) close(); });
  input.addEventListener('input', run);
  document.addEventListener('keydown', keyH);
  (document.getElementById('nx-overlay-root') || document.body).appendChild(back);
  run();
  setTimeout(()=>input.focus(), 20);
};

/* a search box at the top of the settings nav */
NX.afterRouteRender('settings', function(view){
  const nav = q('.set-nav', view);
  if(!nav || nav.previousElementSibling) return;
  const box = h(`<div class="set-search">
    ${icon('search')}<input id="set-q" placeholder="Filter settings…" aria-label="Filter settings">
    <span class="kbd">/</span>
  </div>`);
  nav.parentNode.insertBefore(box, nav);
  const inp = q('#set-q', box);
  inp.addEventListener('input', ()=>{
    const t = inp.value.trim().toLowerCase();
    qa('.set-nav [data-s]', view).forEach(b=>{
      const label = b.textContent.trim().toLowerCase();
      const hay = (b.dataset.s + ' ' + label).toLowerCase();
      b.style.display = (!t || hay.indexOf(t) > -1) ? '' : 'none';
    });
    /* also hide the body when the filter matches nothing */
    const any = [...nav.querySelectorAll('[data-s]')].some(b => b.style.display !== 'none');
    const body = q('#set-body', view);
    if(body) body.style.display = (t && !any) ? 'none' : '';
  });
  inp.addEventListener('keydown', e=>{
    if(e.key === 'Escape'){ inp.value = ''; inp.dispatchEvent(new Event('input')); inp.blur(); }
    if(e.key === 'Enter'){
      const first = [...nav.querySelectorAll('[data-s]')].find(b => b.style.display !== 'none');
      if(first) first.click();
    }
  });
});
document.addEventListener('keydown', e=>{
  const inField = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA');
  if(e.key === '/' && !inField && NX.router.currentName === 'settings'){
    e.preventDefault();
    const i = q('#set-q');
    if(i) i.focus();
  }
});
})(window.NX);


/* ══════════ 40-widget.js ══════════ */
/* ============================================================
   PebbleX v0.1 — 40-widget.js
   Desktop Widget:
   - Draggable: native data-tauri-drag-region + in-app drag
   - Mini / Compact mode: toggle between full card & mini pill
   - Quick Note: capture thoughts directly into Notes vault
   - Quick Tasks: check off tasks right from desktop
   - Focus session / Pomodoro control
   - One-click launch to bring full PebbleX app to front
   ============================================================ */
(function(NX){
'use strict';
const { h, q, qa, util:U, icon } = NX;

let isMini = NX.store ? NX.store.get('widgetMini', false) : false;

function widgetHTML(){
  const profile = NX.store.get('profile', NX.defaults.profile);
  const s = NX.store.get('settings', {});
  const t = NX.totals ? NX.totals() : { prod:0, distr:0, total:0 };
  const goalPct = Math.min(100, Math.round((t.prod/60)/(s.focusGoalMin||240)*100));
  const openTasks = NX.store.get('tasks', []).filter(x=>!x.done).slice(0, 2);
  const totalOpenTasks = NX.store.get('tasks', []).filter(x=>!x.done).length;
  const now = new Date();

  return `<div class="widget ${isMini?'mini-mode':''}" id="pebble-widget-box">
    <!-- Header with drag region -->
    <div class="w-head widget-drag-area" data-tauri-drag-region title="Click and drag to move">
      <div class="brand-mark" data-tauri-drag-region>${NX.brandMark()}</div>
      <b data-tauri-drag-region>PebbleX</b>
      <div class="widget-btns">
        <button class="widget-btn-icon" id="wg-mini-toggle" data-tip="${isMini?'Expand widget':'Mini compact mode'}">${isMini?'▼':'▲'}</button>
        <button class="widget-btn-icon" id="wg-open-main" data-tip="Open PebbleX">${icon('rocket',13)}</button>
        <button class="widget-btn-icon" id="wg-close" data-tip="Hide widget">${icon('x',13)}</button>
      </div>
    </div>

    <!-- Mini Mode Content -->
    <div class="w-mini-bar" data-tauri-drag-region>
      <div class="w-mini-clock" id="wg-clock-mini" data-tauri-drag-region>${U.esc(U.hhmm(now))}</div>
      <div class="w-mini-badge" data-tauri-drag-region>Focus ${goalPct}%</div>
      <span class="faint tiny" style="margin-left:auto" data-tauri-drag-region>${totalOpenTasks} task${totalOpenTasks===1?'':'s'}</span>
    </div>

    <!-- Full Mode Content -->
    <div class="w-hide-mini widget-drag-area" data-tauri-drag-region>
      <div class="w-clock" id="wg-clock" data-tauri-drag-region>${U.esc(U.hhmm(now))}</div>
      <div class="w-date" data-tauri-drag-region>${U.esc(now.toLocaleDateString(undefined,{weekday:'short', month:'short', day:'numeric'}))}</div>
    </div>

    <div class="w-score w-hide-mini">
      <span class="w-sec">Focus Goal</span>
      <div class="meter"><i style="width:${goalPct}%"></i></div>
      <b class="small mono-num">${goalPct}%</b>
    </div>

    <div class="w-row w-hide-mini">
      <div class="wr-ic" style="background:var(--green)">${icon('clock')}</div>
      <div style="min-width:0;flex:1"><div class="wr-t">Focus time today</div><div class="wr-v" id="wg-prod">${U.fmtTime(t.prod)}</div></div>
      <button class="btn btn-soft btn-sm" id="wg-pomo-btn" style="padding:4px 8px;font-size:11px">${icon('play',11)} Pomo</button>
    </div>

    <!-- Quick Note Capture -->
    <div class="widget-quick-note w-hide-mini">
      <input id="wg-note-input" placeholder="Quick note… (Enter to save)" maxlength="140">
      <button id="wg-note-save">Save</button>
    </div>

    <!-- Quick Tasks Section -->
    <div class="w-hide-mini w-tasks-wrap">
      <div class="w-tasks-head">
        <span class="w-sec">Tasks (${totalOpenTasks})</span>
        <span class="faint tiny" style="cursor:pointer" id="wg-see-all-tasks">view all</span>
      </div>
      <div class="widget-tasks-list" id="wg-tasks-box">
        ${openTasks.length ? openTasks.map(tk => `
          <div class="widget-task-item">
            <input type="checkbox" data-task-id="${tk.id}">
            <span>${U.esc(tk.name || tk.title || 'Untitled')}</span>
          </div>
        `).join('') : '<div class="faint tiny">All tasks complete! 🎉</div>'}
      </div>
    </div>
  </div>`;
}

function attachWidgetEvents(root){
  if(!root) return;

  // Mini mode toggle
  const miniBtn = root.querySelector('#wg-mini-toggle');
  if(miniBtn){
    miniBtn.onclick = async (e) => {
      e.stopPropagation();
      isMini = !isMini;
      NX.store.set('widgetMini', isMini);
      const box = root.querySelector('#pebble-widget-box');
      if(box){
        box.classList.toggle('mini-mode', isMini);
        miniBtn.textContent = isMini ? '▼' : '▲';
        miniBtn.dataset.tip = isMini ? 'Expand widget' : 'Mini compact mode';
        miniBtn.setAttribute('title', isMini ? 'Expand widget' : 'Mini compact mode');
        miniBtn.setAttribute('aria-label', isMini ? 'Expand widget' : 'Mini compact mode');
      }
      /* shrink/grow the actual window — without this the content shrank but
         the 320x490 window stayed the same size, so mini mode looked broken */
      try{
        if(NX.native && NX.native.available && typeof NX.native.widgetSize === 'function'){
          await NX.native.widgetSize(isMini);
        }
      }catch(err){}
    };
  }

  // Right-click menu for the widget
  const menuBox = root.querySelector('#pebble-widget-box') || root;
  if(menuBox && !menuBox.__hasCtx){
    menuBox.__hasCtx = true;
    menuBox.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      e.stopPropagation();
      const s = NX.store.get('settings', {});
      const items = [
        { label:'Open PebbleX', icon:'rocket', onClick:()=> openMain() },
        '-',
        { label: isMini ? 'Exit mini mode' : 'Mini mode', icon:'minimize',
          onClick:()=>{ const b = root.querySelector('#wg-mini-toggle'); if(b) b.click(); } },
        { label:'Start a focus session', icon:'target',
          onClick:()=>{ const b = root.querySelector('#wg-pomo-btn'); if(b) b.click(); } },
        '-',
        { label: s.widgetOnTop === false ? 'Pin on top' : 'Unpin from top', icon:'pin',
          onClick:()=>{ const st = NX.store.get('settings',{}); st.widgetOnTop = st.widgetOnTop === false; NX.store.set('settings', st); } },
        '-',
        { label:'Hide widget', icon:'x', danger:true, onClick:()=> NX.widget.apply(false) }
      ];
      /* NX.menu anchors to an element; a zero-size probe at the cursor keeps
         the menu exactly under the pointer */
      const probe = h('<div style="position:fixed;left:' + e.clientX + 'px;top:' + e.clientY + 'px;width:0;height:0"></div>');
      document.body.appendChild(probe);
      try{ NX.menu(probe, items); }catch(err){ console.error(err); }
      setTimeout(()=> probe.remove(), 0);
    });
  }

  function openMain(){
    try{
      if(NX.native.available && typeof NX.native.showMain === 'function') NX.native.showMain();
    }catch(e){}
  }

  // Open full app
  const openBtn = root.querySelector('#wg-open-main');
  if(openBtn){
    openBtn.onclick = (e) => {
      e.stopPropagation();
      if(NX.native.available){
        NX.native.showMain();
      } else {
        NX.router.go('dashboard');
      }
    };
  }

  // Close widget
  const closeBtn = root.querySelector('#wg-close');
  if(closeBtn){
    closeBtn.onclick = (e) => {
      e.stopPropagation();
      NX.widget.apply(false);
    };
  }

  // Pomodoro quick action
  const pomoBtn = root.querySelector('#wg-pomo-btn');
  if(pomoBtn){
    pomoBtn.onclick = (e) => {
      e.stopPropagation();
      NX.router.go('timeless');
      if(NX.native.available) NX.native.showMain();
      setTimeout(()=>{ if(NX.pomo && NX.pomo.start) NX.pomo.start(); }, 120);
    };
  }

  // Quick note save
  const noteInput = root.querySelector('#wg-note-input');
  const noteSave = root.querySelector('#wg-note-save');
  const handleSaveNote = () => {
    if(!noteInput) return;
    const txt = noteInput.value.trim();
    if(!txt) return;
    const notes = NX.store.get('notes', []);
    const n = {
      id: U.uid('nt'),
      title: txt.slice(0, 40),
      body: txt,
      tags: ['quick-capture'],
      pinned: false,
      updated: Date.now(),
      folder: 'Quick'
    };
    notes.unshift(n);
    NX.store.set('notes', notes);
    noteInput.value = '';
    NX.toastOk('Note saved to vault', n.title);
    NX.sfx.play('ok');
  };
  if(noteSave) noteSave.onclick = handleSaveNote;
  if(noteInput) noteInput.onkeydown = (e) => { if(e.key === 'Enter') handleSaveNote(); };

  // Task checkoff directly in widget
  root.querySelectorAll('[data-task-id]').forEach(cb => {
    cb.onchange = () => {
      const id = cb.dataset.taskId;
      const tasks = NX.store.get('tasks', []);
      const t = tasks.find(x => x.id === id);
      if(t){
        t.done = true;
        t.doneAt = Date.now();
        NX.store.set('tasks', tasks);
        NX.sfx.play('ok');
        refreshWidget();
      }
    };
  });

  const seeAll = root.querySelector('#wg-see-all-tasks');
  if(seeAll){
    seeAll.onclick = () => {
      NX.router.go('todo');
      if(NX.native.available) NX.native.showMain();
    };
  }

  // Desktop Dragging (Native Tauri startDragging on drag areas)
  root.querySelectorAll('.widget-drag-area').forEach(el => {
    el.onmousedown = (e) => {
      if(e.button !== 0 || e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT') return;
      if(NX.native.available && NX.native.mode === 'tauri'){
        NX.native.startDragging();
      }
    };
  });
}

function makeInAppDraggable(el){
  let isDown = false, startX, startY, startLeft, startTop;
  el.addEventListener('mousedown', (e) => {
    if(e.target.tagName === 'BUTTON' || e.target.tagName === 'INPUT') return;
    isDown = true;
    startX = e.clientX;
    startY = e.clientY;
    const rect = el.getBoundingClientRect();
    startLeft = rect.left;
    startTop = rect.top;
    e.preventDefault();
  });

  window.addEventListener('mousemove', (e) => {
    if(!isDown) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    el.style.left = Math.max(10, Math.min(window.innerWidth - el.offsetWidth - 10, startLeft + dx)) + 'px';
    el.style.top = Math.max(10, Math.min(window.innerHeight - el.offsetHeight - 10, startTop + dy)) + 'px';
    el.style.right = 'auto';
  });

  window.addEventListener('mouseup', () => {
    if(isDown){
      isDown = false;
      const pos = { left: el.style.left, top: el.style.top };
      NX.store.set('widgetFloatingPos', pos);
    }
  });
}

function refreshWidget(){
  const box = q('#pebble-widget-box');
  if(!box) return;
  const now = new Date();
  const s = NX.store.get('settings', {});
  const t = NX.totals ? NX.totals() : { prod:0, distr:0 };
  const goalPct = Math.min(100, Math.round((t.prod/60)/(s.focusGoalMin||240)*100));

  const setTxt = (id, txt) => { const el = box.querySelector('#'+id); if(el) el.textContent = txt; };
  setTxt('wg-clock', U.hhmm(now));
  setTxt('wg-clock-mini', U.hhmm(now));
  setTxt('wg-prod', U.fmtTime(t.prod));
  const meter = box.querySelector('.meter i');
  if(meter) meter.style.width = goalPct + '%';
}

const widget = {
  open: false,
  floating: null,

  async toggle(){
    await this.apply(!this.open);
  },

  async apply(forceOpen){
    const s = NX.store.get('settings', {});
    const want = forceOpen !== undefined ? !!forceOpen : !!s.widgetEnabled;
    this.open = want;
    if(forceOpen !== undefined){
      s.widgetEnabled = want;
      NX.store.set('settings', s);
    }

    if(NX.native.available && NX.native.mode === 'tauri'){
      await NX.native.widgetToggle(want);
    } else {
      if(want) this.showFloating();
      else this.hideFloating();
    }
  },

  showFloating(){
    if(this.floating){
      this.floating.style.display = '';
      return;
    }
    const savedPos = NX.store.get('widgetFloatingPos', { left: '', top: '' });
    const posStyle = savedPos.left ? `left:${savedPos.left};top:${savedPos.top};right:auto;` : `right:18px;top:70px;`;

    const el = h(`<div id="nx-float-widget" style="position:fixed;${posStyle}width:290px;z-index:9000">${widgetHTML()}</div>`);
    document.getElementById('nx-widget-root').appendChild(el);
    this.floating = el;
    attachWidgetEvents(el);
    makeInAppDraggable(el);
    refreshWidget();
  },

  hideFloating(){
    if(this.floating){
      this.floating.remove();
      this.floating = null;
    }
  }
};

NX.widget = widget;

/* Router registration for dedicated Tauri widget window */
NX.router.register('widget', {
  title: 'Pebble Widget',
  layout: 'widget',
  icon: 'widget',
  render(app){
    document.documentElement.classList.add('widget-mode');
    document.body.classList.add('widget-mode');
    const splash = document.getElementById('nx-splash');
    if(splash) try{ splash.remove(); }catch(e){}
    app.innerHTML = '';
    let root = document.getElementById('nx-widget-root');
    if(!root){
      root = document.createElement('div');
      root.id = 'nx-widget-root';
      document.body.appendChild(root);
    }
    root.innerHTML = widgetHTML();
    attachWidgetEvents(root);
    /* if the widget was left in mini mode, shrink the window to match —
       otherwise it opens at the full height showing a compact body */
    if(isMini){
      try{
        if(NX.native && NX.native.available && typeof NX.native.widgetSize === 'function'){
          NX.native.widgetSize(true);
        }
      }catch(e){}
    }
  }
});

/* One refresh loop for the whole process, covering both the dedicated widget
   window and the floating in-app widget. It used to be started inside render(),
   which stacked a permanent 1s timer on every re-render of the route. */
const widgetIsMounted = () => !!(document.getElementById('pebble-widget-box') || widget.floating);
setInterval(() => { if(widgetIsMounted()) refreshWidget(); }, 1000);
NX.events.on('notifs:changed', () => { if(widgetIsMounted()) refreshWidget(); });
})(window.NX);


/* ══════════ 41-ux.js ══════════ */
/* ============================================================
   PebbleX v0.1 — 41-ux.js
   Systemic UX fixes:
     · one overlay stack — Escape always closes the top-most thing
     · skeleton loaders for anything that waits
     · inline form validation (no more shake-only errors)
     · cancelable Pel AI streaming with a real Stop button
     · long-text truncation helpers
     · focus rings for custom controls
   ============================================================ */
(function(NX){
'use strict';
const { h, q, qa, util:U, icon } = NX;

/* ============================================================
   1. OVERLAY STACK — one Escape closes the top-most layer
   ============================================================ */
const Overlays = {
  stack: [],
  register(el, close){
    if(!el) return null;
    const entry = { el, close: close || (()=> el.remove()), dead:false };
    this.stack.push(entry);
    return entry;
  },
  unregister(el){
    for(let i=this.stack.length-1;i>=0;i--){
      if(this.stack[i].el === el || this.stack[i].dead) this.stack.splice(i,1);
    }
  },
  /* Reconcile against the DOM instead of trusting the observer:
     MutationObserver callbacks are async, so an overlay opened and
     closed within one tick would otherwise be missed. */
  reconcile(){
    const root = document.getElementById('nx-overlay-root') || document.body;
    if(root){
      const live = root.querySelectorAll(OVERLAY_SEL);
      for(let i=0;i<live.length;i++){
        const el = live[i];
        if(!this.stack.some(e => e.el === el)) this.register(el, () => this.closeEl(el));
      }
    }
    for(let i=this.stack.length-1;i>=0;i--){
      const e = this.stack[i];
      if(e.dead || !e.el || !document.body.contains(e.el)) this.stack.splice(i,1);
    }
    return this.stack;
  },
  closeEl(el){
    if(!el) return;
    if(el.classList.contains('modal-backdrop')){
      const dlg = el.querySelector('.modal');
      if(dlg && NX.closeModal) NX.closeModal(dlg);
      else el.remove();
    } else el.remove();
  },
  top(){
    return this.reconcile()[this.stack.length-1] || null;
  },
  clear(){ this.stack = []; }
};
NX.overlays = Overlays;

const OVERLAY_SEL = '.qs-backdrop, .gs-backdrop, .cmdk-backdrop, .modal-backdrop';

/* keeps the stack warm between events; top() reconciles regardless */
function watchOverlays(){
  const root = document.getElementById('nx-overlay-root') || document.body;
  if(!root) return;
  new MutationObserver(muts=>{
    muts.forEach(m=>{
      (m.addedNodes || []).forEach(node=>{
        if(node.nodeType === 1 && node.matches && node.matches(OVERLAY_SEL)){
          Overlays.register(node, ()=> Overlays.closeEl(node));
        }
      });
      (m.removedNodes || []).forEach(node=>{
        if(node.nodeType === 1) Overlays.unregister(node);
      });
    });
  }).observe(root, { childList:true });
}
if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', watchOverlays);
else watchOverlays();

document.addEventListener('keydown', e=>{
  if(e.key !== 'Escape') return;
  const t = Overlays.top();
  if(!t){
    /* last resort: a stray context menu */
    const m = q('.menu');
    if(m) m.remove();
    return;
  }
  /* capture phase: close once and stop the per-overlay handlers */
  e.preventDefault();
  e.stopPropagation();
  t.dead = true;
  try{ t.close(); }catch(err){ console.error(err); }
  Overlays.prune();
}, true);

/* ============================================================
   2. SKELETONS
   ============================================================ */
NX.skeleton = function(rows, opts){
  opts = opts || {};
  const n = rows || 3;
  return `<div class="nx-skel ${opts.block ? 'block' : ''}">
    ${Array.from({ length:n }, (_,i)=>`
      <div class="skel-row">
        ${opts.avatar === false ? '' : '<div class="skel skel-ic"></div>'}
        <div class="skel-lines">
          <div class="skel" style="width:${70 + (i*13)%28}%"></div>
          <div class="skel" style="width:${38 + (i*17)%40}%"></div>
        </div>
      </div>`).join('')}
  </div>`;
};
/* paint a skeleton, then run the real render on the next frame */
NX.withSkeleton = function(host, skeletonRows, realFn){
  if(!host) return;
  host.innerHTML = NX.skeleton(skeletonRows || 3);
  requestAnimationFrame(()=> requestAnimationFrame(()=>{
    try{ realFn(); }catch(e){ console.error('[skeleton]', e); }
  }));
};

/* the AI page gets a skeleton instead of three bouncing dots */
NX.afterRouteRender('ai', function(view){
  const msgs = q('.ai-msgs', view);
  if(!msgs) return;
  const stop = h(`<button class="btn btn-soft btn-sm ai-stop" id="ai-stop" style="display:none">${icon('x')} Stop</button>`);
  const head = q('.ai-root .chat-head', view);
  if(head) head.appendChild(stop);
  stop.onclick = ()=>{
    if(NX.ai) NX.ai.cancel();
    NX.events.emit('ai:stopped');
  };
});

/* ============================================================
   3. INLINE FORM VALIDATION
   ============================================================ */
NX.formError = function(input, message, opts){
  opts = opts || {};
  if(!input) return false;
  const clear = ()=>{
    input.classList.remove('nx-invalid');
    const m = input.parentElement && input.parentElement.querySelector('.nx-field-error');
    if(m) m.remove();
  };
  clear();
  if(!message) return true;
  input.classList.add('nx-invalid');
  const box = h(`<div class="nx-field-error">${icon('alert',13)}<span>${U.esc(message)}</span></div>`);
  const host = input.parentElement;
  if(host) host.appendChild(box);
  if(opts.focus !== false && typeof input.focus === 'function') input.focus();
  try{ NX.sfx.play('err'); }catch(e){}
  return false;
};
NX.formOk = function(input){ return NX.formError(input, null); };

/* required-field rules, applied on submit */
NX.validate = function(form, rules){
  const out = [];
  Object.keys(rules || {}).forEach(sel=>{
    const el = q(sel, form) || q(sel);
    if(!el) return;
    const rule = rules[sel];
    const v = String(el.value == null ? '' : el.value).trim();
    let msg = null;
    if(rule.required && !v) msg = rule.label ? rule.label + ' is required' : 'This is required';
    else if(rule.min && v.length < rule.min) msg = 'Needs at least ' + rule.min + ' characters';
    else if(rule.max && v.length > rule.max) msg = 'Keep it under ' + rule.max + ' characters';
    else if(rule.email && v && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) msg = 'That email does not look right';
    else if(rule.number && v && isNaN(Number(v))) msg = 'Numbers only';
    if(msg){ NX.formError(el, msg); out.push(sel); }
    else NX.formOk(el);
  });
  return out;
};

/* live-clear the error as soon as the field becomes valid */
document.addEventListener('input', e=>{
  const el = e.target;
  if(!el || !el.classList || !el.classList.contains('nx-invalid')) return;
  if(String(el.value || '').trim()) NX.formOk(el);
});

/* ============================================================
   4. TRUNCATION
   ============================================================ */
NX.truncate = function(text, max){
  const s = String(text == null ? '' : text);
  if(s.length <= max) return s;
  return s.slice(0, Math.max(1, max-1)).trimEnd() + '…';
};

/* ============================================================
   5. AI — cancelable streaming with a skeleton + Stop button
   ============================================================ */
NX.afterRouteRender('ai', function(view){
  const oldInp = q('#ai-input', view);
  const msgs = q('.ai-msgs', view);
  if(!oldInp || !msgs) return;

  /* The module binds its own keydown/click handlers with addEventListener,
     which cannot be un-bound. Clone the nodes so those listeners go away
     and only the cancelable implementation below remains. */
  const inp = oldInp.cloneNode(true);
  oldInp.parentNode.replaceChild(inp, oldInp);
  const sendBtn = q('#ai-send', view);
  let liveBtn = null;
  if(sendBtn){
    liveBtn = sendBtn.cloneNode(true);
    sendBtn.parentNode.replaceChild(liveBtn, sendBtn);
    liveBtn.style.opacity = '';
  }

  let busy = false;
  const render = (full, caret) =>
    (NX.chatMd ? NX.chatMd(full) : U.esc(full).replace(/\n/g,'<br>')) + (caret ? '<span class="ai-caret"></span>' : '');

  async function ask(){
    const text = inp.value.trim();
    if(!text || busy) return;
    if(!NX.ai || !NX.ai.ask){ NX.formError(inp, 'Pel AI is not available'); return; }
    NX.formOk(inp);
    busy = true;
    inp.value = '';
    if(liveBtn) liveBtn.style.opacity = .4;

    const mine = h(`<div class="ai-msg user"><div class="am-bubble">${U.esc(text)}</div></div>`);
    msgs.appendChild(mine);
    const reply = h(`<div class="ai-msg ai"><div class="am-bubble">${NX.skeleton(2, { avatar:false })}</div></div>`);
    msgs.appendChild(reply);
    msgs.scrollTop = msgs.scrollHeight;

    const stopBtn = q('#ai-stop', view);
    if(stopBtn) stopBtn.style.display = '';
    let stopped = false;
    const off = NX.events.on('ai:stopped', ()=>{ stopped = true; });

    try{
      const out = await NX.ai.ask(text, {
        onDelta: full =>{
          if(stopped) return;
          reply.innerHTML = `<div class="am-bubble">${render(full, true)}</div>`;
          msgs.scrollTop = msgs.scrollHeight;
        }
      });
      if(stopped){
        reply.innerHTML = `<div class="am-bubble"><span class="ai-typing">stopped — nothing was saved to history</span></div>`;
      } else {
        reply.innerHTML = `<div class="am-bubble">${render(out || '', false)}</div>`;
        const cfg = NX.store.get('ai', { history:[] });
        if(cfg && Array.isArray(cfg.history)){
          cfg.history.push({ role:'user', content:text });
          cfg.history.push({ role:'assistant', content:out || '' });
          NX.store.set('ai', cfg);
        }
      }
    }catch(e){
      /* an abort can surface either as AbortError or as a plain network
         failure, so treat "stopped" as the winner either way */
      if(stopped){
        reply.innerHTML = `<div class="am-bubble"><span class="ai-typing">stopped — nothing was saved to history</span></div>`;
      } else {
        reply.innerHTML = `<div class="am-bubble error">${U.esc(e.message || 'Could not reach the AI service')}</div>`;
        if(NX.net){ NX.net.aiDown = true; NX.events.emit('net:changed'); }
      }
    }finally{
      off();
      if(stopBtn) stopBtn.style.display = 'none';
      if(liveBtn) liveBtn.style.opacity = '';
      msgs.scrollTop = msgs.scrollHeight;
      busy = false;
    }
  }

  if(liveBtn) liveBtn.onclick = ask;
  inp.addEventListener('keydown', e=>{
    if(e.key !== 'Enter' || e.shiftKey) return;
    e.preventDefault();
    if(!inp.value.trim()){
      NX.formError(inp, 'Ask Pel something first');
      return;
    }
    ask();
  });
});

/* flag AI reachability so the topbar can say so */
NX.events.on('store:ai', ()=>{ if(NX.net){ NX.net.aiDown = false; NX.events.emit('net:changed'); } });
})(window.NX);


/* ══════════ 42-chat.js ══════════ */
/* ============================================================
   PebbleX v0.1 — 42-chat.js
   Chat polish for Pel AI:
     · real Markdown rendering (safe — escapes before formatting)
     · proper bubble layout, timestamps, hover actions
     · copy answer, regenerate the last answer
     · scroll-to-bottom affordance
   ============================================================ */
(function(NX){
'use strict';
const { h, q, qa, util:U, icon } = NX;

/* ============================================================
   1. SAFE MARKDOWN
   Everything is HTML-escaped first, so nothing from the model can
   inject markup. Only the tags produced here are ever emitted.
   ============================================================ */
function inline(s){
  return U.esc(s)
    .replace(/`([^`\n]+)`/g, (m,c)=> '<code class="md-code">' + c + '</code>')
    .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(\[])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/(^|[\s(\[])_([^_\n]+)_/g, '$1<em>$2</em>')
    .replace(/~~([^~\n]+)~~/g, '<del>$1</del>')
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g,
      (m,t,h)=> '<a class="md-link" href="'+h+'" target="_blank" rel="noopener noreferrer">'+t+'</a>')
    .replace(/(^|\s)(https?:\/\/[^\s<)]+)/g,
      (m,pre,u)=> pre + '<a class="md-link" href="'+u+'" target="_blank" rel="noopener noreferrer">'+u+'</a>');
}

function renderMarkdown(src){
  const blocks = [];
  let text = String(src == null ? '' : src);

  /* fenced code first, stashed behind sentinels */
  text = text.replace(/```([\w+#-]*)[ \t]*\r?\n?([\s\S]*?)```/g, (m, lang, code)=>{
    blocks.push({ lang: lang || '', code: String(code).replace(/\n$/, '') });
    return '\0B' + (blocks.length - 1) + '\0';
  });
  /* inline code stashed too, so list/heading parsing cannot touch it */
  const inlineCode = [];
  text = text.replace(/`([^`\n]+)`/g, (m,c)=>{
    inlineCode.push(c);
    return '\0I' + (inlineCode.length - 1) + '\0';
  });

  const lines = text.split(/\r?\n/);
  const out = [];
  let list = null;           /* 'ul' | 'ol' */
  let para = [];
  let quote = [];

  function flushPara(){
    if(!para.length) return;
    out.push('<p class="md-p">' + inline(para.join(' ')) + '</p>');
    para = [];
  }
  function flushList(){
    if(!list) return;
    out.push('</' + list + '>');
    list = null;
  }
  function flushQuote(){
    if(!quote.length) return;
    out.push('<blockquote class="md-quote">' + inline(quote.join(' ')) + '</blockquote>');
    quote = [];
  }
  function flushAll(){ flushPara(); flushList(); flushQuote(); }

  for(let i=0;i<lines.length;i++){
    const raw = lines[i];
    const line = raw.replace(/\s+$/,'');

    if(/^\0B\d+\0$/.test(line.trim())){
      flushAll();
      const b = blocks[+line.trim().match(/^\0B(\d+)\0$/)[1]];
      out.push('<div class="md-codeblock"><div class="md-codeblock-h"><span>' +
        U.esc(b.lang || 'code') + '</span><button class="md-copy-btn" data-copy-code>Copy</button></div>' +
        '<pre class="md-pre"><code>' + U.esc(b.code) + '</code></pre></div>');
      continue;
    }

    if(!line.trim()){ flushAll(); continue; }

    let m;
    /* horizontal rule */
    if(/^([-*_])\s*(\1\s*){2,}$/.test(line.trim())){
      flushAll();
      out.push('<hr class="md-hr">');
      continue;
    }
    /* heading */
    if((m = line.match(/^(#{1,6})\s+(.*)$/))){
      flushAll();
      const lvl = Math.min(3, m[1].length);
      out.push('<div class="md-h md-h' + lvl + '">' + inline(m[2]) + '</div>');
      continue;
    }
    /* blockquote */
    if((m = line.match(/^>\s?(.*)$/))){
      flushPara(); flushList();
      quote.push(m[1]);
      continue;
    }
    if(quote.length && !/^>/.test(line)) flushQuote();

    /* task list — accepts [x] and the emoji boxes models actually emit */
    if((m = line.match(/^\s*[-*+]\s+\[([ xX])\]\s+(.*)$/))){
      flushPara();
      if(list !== 'ul'){ flushList(); out.push('<ul class="md-ul md-tasks">'); list = 'ul'; }
      const on = m[1].toLowerCase() === 'x';
      out.push('<li class="md-task' + (on ? ' done' : '') + '">' +
        '<span class="md-box">' + (on ? icon('check', 11) : '') + '</span>' +
        '<span>' + inline(m[2]) + '</span></li>');
      continue;
    }
    /* bullet list — ✅ / ☐ / ☑ become real boxes too */
    if((m = line.match(/^\s*[-*+]\s+(.*)$/))){
      flushPara();
      const box = m[1].match(/^\s*(\[([ xX])\]|✅|☑️?|✔️?|⛔|☐️?|□|◻️?)\s*(.*)$/);
      if(box){
        if(list !== 'ul'){ flushList(); out.push('<ul class="md-ul md-tasks">'); list = 'ul'; }
        const glyph = box[2] !== undefined ? box[2].toLowerCase() === 'x' : /[✅☑✔]/.test(box[1]);
        const rest = box[3] !== undefined ? box[3] : box[1].replace(/^\s*\[([ xX])\]\s*/, '');
        out.push('<li class="md-task' + (glyph ? ' done' : '') + '">' +
          '<span class="md-box">' + (glyph ? icon('check', 11) : '') + '</span>' +
          '<span>' + inline(rest) + '</span></li>');
        continue;
      }
      if(list !== 'ul'){ flushList(); out.push('<ul class="md-ul">'); list = 'ul'; }
      out.push('<li>' + inline(m[1]) + '</li>');
      continue;
    }
    /* ordered list */
    if((m = line.match(/^\s*(\d+)[.)]\s+(.*)$/))){
      flushPara();
      if(list !== 'ol'){ flushList(); out.push('<ol class="md-ol">'); list = 'ol'; }
      out.push('<li>' + inline(m[2]) + '</li>');
      continue;
    }
    /* table */
    if(/\|/.test(line) && i + 1 < lines.length && /^\s*\|?[\s:|-]+\|[\s:|-]*$/.test(lines[i+1] || '')){
      flushAll();
      const cells = r => r.trim().replace(/^\||\|$/g,'').split('|').map(c => c.trim());
      const head = cells(line);
      i += 2;
      const body = [];
      while(i < lines.length && /\|/.test(lines[i])){ body.push(cells(lines[i])); i++; }
      i--;
      out.push('<div class="md-table-wrap"><table class="md-table"><thead><tr>' +
        head.map(h2 => '<th>' + inline(h2) + '</th>').join('') + '</tr></thead><tbody>' +
        body.map(r => '<tr>' + r.map(c => '<td>' + inline(c) + '</td>').join('') + '</tr>').join('') +
        '</tbody></table></div>');
      continue;
    }

    if(list) flushList();
    para.push(line.trim());
  }
  flushAll();

  /* put inline code and code blocks back */
  let html = out.join('');
  html = html.replace(/\0I(\d+)\0/g, (m,i)=> '<code class="md-code">' + U.esc(inlineCode[+i]) + '</code>');
  html = html.replace(/\0B(\d+)\0/g, ()=> '');
  if(!html) html = '<p class="md-p"></p>';
  return html;
}
NX.chatMd = renderMarkdown;

/* ============================================================
   2. BUBBLE DECORATION — timestamps + actions
   ============================================================ */
const seen = new WeakSet();

function decorateMessages(root){
  const msgs = q('.ai-msgs', root) || root;
  if(!msgs) return;
  qa('.ai-msg', msgs).forEach(msg=>{
    /* the streamed bubble has its innerHTML replaced on every token,
       which wipes anything we appended — so only skip when the meta
       row is genuinely still there */
    if(seen.has(msg) && msg.querySelector('.am-meta')) return;
    const bubble = msg.querySelector('.am-bubble') || msg;
    seen.add(msg);

    /* markdown, but never re-render a streaming caret away */
    if(!bubble.querySelector('.md-p, .md-h, .md-ul, .md-ol, .md-codeblock, .md-table')){
      const raw = bubble.textContent;
      const caret = bubble.querySelector('.ai-caret');
      if(raw && raw.trim()){
        bubble.innerHTML = renderMarkdown(raw) + (caret ? '<span class="ai-caret"></span>' : '');
      }
    }

    const isUser = msg.classList.contains('user');
    const meta = h(`<div class="am-meta">
      <span class="am-time">${U.esc(U.hhmm(Date.now()))}</span>
      ${isUser ? '' : `
        <button class="am-act" data-act="copy" data-tip="Copy answer">${icon('copy',13)}</button>
        <button class="am-act" data-act="regen" data-tip="Ask again">${icon('refresh',13)}</button>`}
    </div>`);
    msg.appendChild(meta);

    qa('[data-act]', meta).forEach(b=>b.onclick = ()=>{
      const text = bubble.textContent || '';
      if(b.dataset.act === 'copy'){
        const done = ()=>NX.toastOk('Copied', text.slice(0,40) + (text.length>40?'…':''));
        if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done, done);
        else done();
      } else {
        const last = [...msgs.querySelectorAll('.ai-msg.user .am-bubble')].pop();
        const prompt = last ? last.textContent.trim() : '';
        if(!prompt){ NX.toastErr('Nothing to repeat', 'Ask something first'); return; }
        msg.scrollIntoView({ block:'center', behavior:'smooth' });
        const inp = q('.ai-root #ai-input', root) || q('#ai-input');
        if(inp){ inp.value = prompt; inp.focus(); }
        NX.toastInfo('Ask again', prompt.slice(0,48));
      }
    });
  });

  /* copy buttons inside code blocks */
  qa('[data-copy-code]', msgs).forEach(b=>{
    if(b._bound) return;
    b._bound = true;
    b.onclick = ()=>{
      const code = b.closest('.md-codeblock').querySelector('code').textContent;
      const done = ()=>NX.toastOk('Code copied', code.split('\n')[0].slice(0,40));
      if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(code).then(done, done);
      else done();
    };
  });
}

/* ============================================================
   3. SCROLL TO BOTTOM
   ============================================================ */
function wireScroll(root){
  const msgs = q('.ai-msgs', root);
  if(!msgs) return;
  let btn = q('.ai-scroll-end', root);
  if(!btn){
    btn = h(`<button class="ai-scroll-end" data-tip="Jump to latest">${icon('chevD',15)}</button>`);
    const rootEl = q('.ai-root', root);
    if(rootEl) rootEl.appendChild(btn);
  }
  const sync = ()=>{
    const far = msgs.scrollHeight - msgs.scrollTop - msgs.clientHeight > 120;
    btn.classList.toggle('show', far);
  };
  msgs.addEventListener('scroll', sync, { passive:true });
  btn.onclick = ()=>{ msgs.scrollTo ? msgs.scrollTo({ top: msgs.scrollHeight, behavior:'smooth' }) : (msgs.scrollTop = msgs.scrollHeight); };
  sync();
}

/* ============================================================
   4. HOOK
   ============================================================ */
NX.afterRouteRender('ai', function(view){
  const msgs = q('.ai-msgs', view);
  if(!msgs) return;
  decorateMessages(view);
  wireScroll(view);
  msgs.scrollTop = msgs.scrollHeight;

  /* keep up as answers stream in */
  if(!msgs._chatObs){
    msgs._chatObs = true;
    new MutationObserver(()=>{
      decorateMessages(view);
      const near = msgs.scrollHeight - msgs.scrollTop - msgs.clientHeight < 200;
      if(near) msgs.scrollTop = msgs.scrollHeight;
      const btn = q('.ai-scroll-end', view);
      if(btn) btn.classList.toggle('show', msgs.scrollHeight - msgs.scrollTop - msgs.clientHeight > 120);
    }).observe(msgs, { childList:true, subtree:true, characterData:true });
  }

  /* suggestion chips: fill the box rather than firing blind */
  const suggest = q('#ai-suggest', view);
  const inp = q('#ai-input', view);
  if(suggest && inp && !suggest._wired){
    suggest._wired = true;
    qa('.chip', suggest).forEach(c=>c.onclick = ()=>{
      inp.value = c.textContent.trim();
      inp.dispatchEvent(new Event('input', { bubbles:true }));
      inp.focus();
      const send = q('#ai-send', view);
      if(send) send.click();
    });
  }
});
})(window.NX);

/* ══════════ 44-weather-icons.js ══════════ */
/* ============================================================
   Animated weather icons.

   The dashboard used a raw emoji glyph for the current conditions, which
   rendered as a flat, inconsistently-sized character that clashed with the
   rest of the UI (and looked wrong next to the real icons). These are drawn
   as inline SVG and animated with CSS: the sun's rays rotate, clouds drift,
   rain and snow fall, lightning flashes, fog slides. They inherit the theme
   colours and honour prefers-reduced-motion / the app's reduce-motion setting.
   ============================================================ */
(function(NX){
'use strict';

const svg = inner => `<svg class="wx-svg" viewBox="0 0 64 64" aria-hidden="true" focusable="false">${inner}</svg>`;

const CLOUD = '<path class="wx-cloud" d="M20 44h24a10 10 0 0 0 .6-20A14 14 0 0 0 18 26.6 9 9 0 0 0 20 44Z"/>';
const CLOUD_SM = '<path class="wx-cloud wx-cloud-sm" d="M26 46h20a8 8 0 0 0 .4-16A11 11 0 0 0 25 31.6 7 7 0 0 0 26 46Z"/>';
const SUN_CORE = '<circle class="wx-sun-core" cx="32" cy="32" r="11"/>';
const RAYS = '<g class="wx-rays">' +
  [0,45,90,135,180,225,270,315].map(a =>
    `<line x1="32" y1="8" x2="32" y2="14" transform="rotate(${a} 32 32)"/>`).join('') + '</g>';

const DROPS = n => Array.from({ length:n }, (_, i) =>
  `<line class="wx-drop" style="--i:${i}" x1="${18 + i*9}" y1="46" x2="${15 + i*9}" y2="56"/>`).join('');

const FLAKES = n => Array.from({ length:n }, (_, i) =>
  `<circle class="wx-flake" style="--i:${i}" cx="${19 + i*9}" cy="48" r="2"/>`).join('');

const ICONS = {
  'clear':        svg(SUN_CORE + RAYS),
  'mostly-clear': svg(RAYS + CLOUD_SM),
  'partly':       svg(SUN_CORE + '<g class="wx-rays-static">' +
                     [30,90,150,210,270,330].map(a =>
                       `<line x1="32" y1="14" x2="32" y2="18" transform="rotate(${a} 32 32)"/>`).join('') +
                     '</g>' + CLOUD_SM),
  'cloudy':       svg('<g class="wx-drift-a">' + CLOUD + '</g><g class="wx-drift-b">' + CLOUD_SM + '</g>'),
  'fog':          svg('<g class="wx-drift-a">' + CLOUD + '</g>' +
                     '<g class="wx-fog-bars">' +
                     '<line class="wx-fog" style="--i:0" x1="12" y1="48" x2="46" y2="48"/>' +
                     '<line class="wx-fog" style="--i:1" x1="16" y1="54" x2="52" y2="54"/>' +
                     '<line class="wx-fog" style="--i:2" x1="12" y1="60" x2="42" y2="60"/>' +
                     '</g>'),
  'drizzle':      svg(CLOUD + '<g class="wx-fall-slow">' + DROPS(3) + '</g>'),
  'rain':         svg(CLOUD + '<g class="wx-fall">' + DROPS(4) + '</g>'),
  'showers':      svg('<g class="wx-drift-a">' + CLOUD + '</g><g class="wx-fall">' + DROPS(4) + '</g>'),
  'snow':         svg(CLOUD + '<g class="wx-fall-slow">' + FLAKES(4) + '</g>'),
  'storm':        svg('<g class="wx-darken">' + CLOUD + '</g>' +
                     '<g class="wx-fall">' + DROPS(3) + '</g>' +
                     '<path class="wx-bolt" d="M33 44l-7 12h5l-2 9 9-13h-5l3-8Z"/>')
};
ICONS.cloudy = ICONS.cloudy || svg(CLOUD);

/* Build the markup once per kind and cache it. */
const _cache = new Map();
NX.wxIcon = function(kind, cls){
  const k = kind || 'cloudy';
  let inner = _cache.get(k);
  if(inner === undefined){
    inner = ICONS[k] || ICONS.cloudy;
    _cache.set(k, inner);
  }
  return `<span class="wx-icon ${cls || ''}" data-wx="${k}">${inner}</span>`;
};

/* The dashboard used to print the emoji straight into the title text. */
NX.wxLabel = function(w){
  return `${w.temp}°C — ${U.esc(w.city)}`;
};
})(window.NX);

/* ══════════ 99-boot.js ══════════ */
/* ============================================================
   PebbleX v0.1 — 99-boot.js
   Boot sequence: defaults → backend restore → route decision.

   Window modes (Tauri):
   login   → this is the small LOGIN window: ALWAYS the login
             screen, engines off, closing it quits the app
             (handled natively). Never renders the full app.
   main    → this is the MAIN window: boot straight to
             the dashboard and start every engine immediately.
   widget  → desktop widget window: mini dashboard.
   web     → classic session gate (login route when no session).
   ============================================================ */
(function(NX){
'use strict';

const params = new URLSearchParams(location.search);
const PEBBLE_WIN = window.__PEBBLE_WINDOW__ || '';
const AUTH_WINDOW = params.has('auth') || PEBBLE_WIN === 'login';
const MAIN_WINDOW = params.has('main') || PEBBLE_WIN === 'main';
const WIDGET_WINDOW = params.has('widget') || PEBBLE_WIN === 'widget';

function hideSplash(){
  const s = document.getElementById('nx-splash');
  if(s){
    s.classList.add('fade-out');
    setTimeout(()=>{ try{ s.remove(); }catch(e){} }, 380);
  }
}

/* ============================================================
   Boot failsafe.

   Without this, ANY throw during boot — a script that 404s, a
   backend restore that rejects, a typo in any module — leaves the
   user staring at an infinite splash screen with no message and no
   way forward. That is the worst possible failure mode for a
   packaged desktop app, so boot is wrapped, and a hard timer
   guarantees the splash always comes down.
   ============================================================ */

/* modules that must exist for a healthy boot; a missing one is
   almost always a file that never shipped in the build */
const REQUIRED = ['store','router','ensureDefaults','restoreBackend','renderShell','events','toast','h','q','icon'];

function missingModules(){
  if(!window.NX) return ['window.NX'];
  return REQUIRED.filter(k => window.NX[k] === undefined);
}

let booted = false;

function bootFailed(err){
  booted = true;
  clearTimeout(failsafe);
  hideSplash();

  /* if the app is salvageable, get the user in rather than leaving
     them on a dead screen */
  const canContinue = !!(window.NX && window.NX.router && window.NX.renderShell);
  const missing = missingModules();
  const msg = String((err && (err.stack || err.message)) || err || 'unknown boot failure');

  let box = document.getElementById('nx-boot-error');
  if(!box){
    box = document.createElement('div');
    box.id = 'nx-boot-error';
    box.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;'
      + 'justify-content:center;background:rgba(8,10,14,.94);backdrop-filter:blur(8px);'
      + 'font:13px/1.55 ui-sans-serif,system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#e8ecf4;padding:24px';
    document.body.appendChild(box);
  }
  box.innerHTML =
      '<div style="max-width:680px;width:100%;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.1);'
    + 'border-radius:16px;padding:26px 28px;box-shadow:0 24px 60px rgba(0,0,0,.5)">'
    + '<div style="font-size:15px;font-weight:650;margin-bottom:6px">PebbleX could not finish starting</div>'
    + '<div style="color:#9aa4b8;margin-bottom:16px">'
    + (missing.length
        ? 'These modules did not load: <b style="color:#e8ecf4">' + missing.join(', ') + '</b>'
        : 'The app started but an initialisation step failed.')
    + '</div>'
    + '<pre style="max-height:230px;overflow:auto;margin:0 0 18px;padding:12px 14px;background:rgba(0,0,0,.34);'
    + 'border:1px solid rgba(255,255,255,.07);border-radius:10px;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;'
    + 'color:#ffb4a2;white-space:pre-wrap;word-break:break-word">' + String(msg).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c])) + '</pre>'
    + '<div style="display:flex;gap:9px;flex-wrap:wrap">'
    + (canContinue
        ? '<button id="nx-boot-go" style="padding:9px 16px;border-radius:9px;border:1px solid rgba(255,255,255,.16);'
          + 'background:rgba(255,255,255,.09);color:#e8ecf4;font:inherit;font-weight:600;cursor:pointer">Continue anyway</button>'
        : '')
    + '<button id="nx-boot-reload" style="padding:9px 16px;border-radius:9px;border:1px solid rgba(255,255,255,.16);'
      + 'background:rgba(255,255,255,.05);color:#e8ecf4;font:inherit;cursor:pointer">Reload</button>'
    + '</div></div>';

  const go = document.getElementById('nx-boot-go');
  if(go) go.onclick = ()=>{ try{ box.remove(); }catch(e){} try{ NX.router.start(); NX.router.go('dashboard'); }catch(e){} };
  const re = document.getElementById('nx-boot-reload');
  if(re) re.onclick = ()=> location.reload();

  try{ console.error('[PebbleX] boot failed', err, '| missing:', missing); }catch(e){}
}

/* hard ceiling: even if boot() never settles (hangs on an await),
   the splash comes down and the reason is surfaced */
const failsafe = setTimeout(()=>{
  if(booted) return;
  bootFailed(new Error('Startup did not complete within 10 seconds.'));
}, 10000);

/* a <script> that fails to load fires an error event on the element,
   which does not bubble to window.onerror — catch those explicitly */
window.addEventListener('error', ev=>{
  if(ev && ev.target && ev.target !== window && ev.target.tagName === 'SCRIPT'){
    console.error('[PebbleX] script failed to load:', ev.target.src || ev.target.dataset.src || '(inline)');
  }
}, true);

async function boot(){
  try{
  await start();
  booted = true;
  clearTimeout(failsafe);
  }catch(e){ bootFailed(e); }
}

async function start(){
  NX.ensureDefaults();

  /* theme before first paint */
  const s = NX.store.get('settings', {});
  document.documentElement.setAttribute('data-theme', s.theme || 'elera');
  if(s.compactMode) document.documentElement.style.setProperty('font-size','13px');

  /* restore desktop backend mirror (local storage backend) */
  await NX.restoreBackend();
  NX.ensureDefaults();

  /* router */
  NX.router.start();

  const hash = (location.hash||'').replace(/^#\/?/, '').split('/')[0];

  /* widget window */
  if(WIDGET_WINDOW || hash === 'widget'){
    hideSplash();
    NX.router.go('widget');
    return;
  }

  /* ---------- LOGIN WINDOW: login screen only, nothing else ---------- */
  if(AUTH_WINDOW){
    hideSplash();
    NX.router.go('login');
    console.log('%cPebbleX login window ready', 'color:#7CD56E;font-weight:bold');
    return;
  }

  /* ---------- MAIN WINDOW (native): Rust guarantees the handoff ---------- */
  if(MAIN_WINDOW && NX.native.available && NX.native.mode === 'tauri'){
    hideSplash();
    const sess = NX.store.get('session', null);
    if(!sess || !sess.authed) NX.store.set('session', { authed:true, at:Date.now() });
    NX.router.go(NX.router.routes[hash] ? hash : 'dashboard');
    startEngines();
    return;
  }

  /* ---------- WEB / fallback: classic session gate ---------- */
  hideSplash();
  const authed = NX.login.isAuthed();
  const auth = NX.store.get('auth', null);
  if(hash === 'login' || !authed || (auth && auth.pinHash && !authed)){
    NX.router.go('login');
    return;
  }
  NX.router.go(NX.router.routes[hash] ? hash : 'dashboard');
  startEngines();
}

function startEngines(){
  try{ NX.timeless.start(); }catch(e){ console.error('timeless', e); }
  try{ NX.reminderScheduler.start(); }catch(e){ console.error('reminders', e); }
  /* The widget is NOT auto-opened at boot. It used to be, because
     settings.widgetEnabled defaulted to true — so a desktop widget popped up
     unbidden on every launch, and creating that window during boot is what
     wedged the UI thread. It is now opened deliberately: the taskbar button,
     Shift+W, the action palette, or Settings. */
  try{ NX.extsync.start(); }catch(e){ console.error('extsync', e); }

  /* listen for profile handoff from login window */
  try {
    if(window.__TAURI__ && window.__TAURI__.event && typeof window.__TAURI__.event.listen === 'function'){
      window.__TAURI__.event.listen('profile-ready', async ()=>{
        try {
          await NX.restoreBackend();
          const p = NX.store.get('profile', NX.defaults.profile);
          NX.events.emit('profile:updated', p);
          NX.router.go('dashboard');
        } catch(e){}
      });
    }
  } catch(e){}

  /* first-run onboarding (or what's-new for upgraders) */
  try{
    if(!NX.store.get('onboarded')) NX.onboarding.start();
    else NX.onboarding.maybeWhatsNew();
  }catch(e){ console.error('onboarding', e); }

  /* cross-tab sync (web mode nicety) */
  window.addEventListener('storage', e=>{
    if(e.key && e.key.startsWith('pebble.')){
      const k = e.key.slice(7);
      NX.events.emit('store:'+k);
    }
  });

  /* save on exit (flush mirror) */
  window.addEventListener('beforeunload', ()=>{
    try{ if(NX.native.available) NX.native.invoke('save_workspace', { data: JSON.stringify(NX.store.dump()) }); }catch(e){}
  });
}

/* JS-side error capture → bug trail (visible in Settings → Reliability) */
window.addEventListener('error', ev=>{
  try{
    const log = NX.store.get('jsErrors', []);
    log.unshift({ msg:String(ev.message||'error'), src:String(ev.filename||'').split('/').pop(), line:ev.lineno||0, ts:Date.now() });
    NX.store.set('jsErrors', log.slice(0, 30));
  }catch(e){}
});
window.addEventListener('unhandledrejection', ev=>{
  try{
    const log = NX.store.get('jsErrors', []);
    log.unshift({ msg:'promise: ' + String(ev.reason||''), src:'', line:0, ts:Date.now() });
    NX.store.set('jsErrors', log.slice(0, 30));
  }catch(e){}
});

console.log('%cPebbleX v0.1 ready', 'color:#7CD56E;font-weight:bold');
if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})(window.NX);
